<?php require '../config/database.php'; require_once '../config/auth.php'; require_role('trainer'); $rows=mysqli_query($conn,"SELECT u.full_name,u.email,m.goal,m.height_cm,m.weight_kg FROM members m JOIN users u ON m.user_id=u.id"); ?>
